<?php
declare(strict_types=1);
final class CourseService
{
    public function save(array $data): int { Validator::required($data,['program_id'=>'البرنامج','code'=>'رمز المقرر','name'=>'اسم المقرر','credits'=>'الساعات']);$id=(int)($data['id']??0);$program=(int)$data['program_id'];$values=[$program,trim($data['code']),trim($data['name']),(int)$data['credits'],!empty($data['is_required'])?1:0];if($values[3]<1||$values[3]>12)throw new InvalidArgumentException('عدد الساعات يجب أن يكون بين 1 و12.');$repo=new CourseRepository();return Database::transaction(function()use($repo,$id,$values,$data,$program){if($id>0){if(!$repo->find($id))throw new InvalidArgumentException('المقرر غير موجود.');$repo->update($id,$values);$courseId=$id;}else{$courseId=$repo->create($values);}Database::connection()->prepare('DELETE FROM course_programs WHERE course_id=?')->execute([$courseId]);$programs=array_unique(array_map('intval',(array)($data['shared_program_ids']??[])));if(!in_array($program,$programs,true))array_unshift($programs,$program);$st=Database::connection()->prepare('INSERT IGNORE INTO course_programs(course_id,program_id) VALUES(?,?)');foreach($programs as $pid)if($pid>0)$st->execute([$courseId,$pid]);audit($id?'UPDATE':'CREATE','course',$courseId,['programs'=>$programs]);return $courseId;}); }
    public function delete(int $id): void {$r=new CourseRepository();if(!$r->find($id))throw new InvalidArgumentException('المقرر غير موجود.');if($r->hasEnrollments($id))throw new InvalidArgumentException('لا يمكن حذف مقرر تم تسجيله لطلاب.');$r->delete($id);audit('DELETE','course',$id);}
}
